import{_ as e,o as a,c as r,a2 as s}from"./chunks/framework.D66Xq0Kv.js";const p=JSON.parse('{"title":"FAQ & Solução de Problemas (Troubleshooting)","description":"","frontmatter":{},"headers":[],"relativePath":"pt-br/05-faq-e-troubleshooting.md","filePath":"pt-br/05-faq-e-troubleshooting.md"}'),t={name:"pt-br/05-faq-e-troubleshooting.md"};function i(n,o,d,l,c,u){return a(),r("div",null,[...o[0]||(o[0]=[s('<h1 id="faq-solucao-de-problemas-troubleshooting" tabindex="-1">FAQ &amp; Solução de Problemas (Troubleshooting) <a class="header-anchor" href="#faq-solucao-de-problemas-troubleshooting" aria-label="Permalink to &quot;FAQ &amp; Solução de Problemas (Troubleshooting)&quot;">​</a></h1><blockquote><p><strong>Perguntas Frequentes, Dicas de Depuração e Resolução de Erros</strong></p></blockquote><hr><h2 id="_1-perguntas-frequentes-faq" tabindex="-1">1. Perguntas Frequentes (FAQ) <a class="header-anchor" href="#_1-perguntas-frequentes-faq" aria-label="Permalink to &quot;1. Perguntas Frequentes (FAQ)&quot;">​</a></h2><h3 id="posso-usar-o-softforge-sem-docker" tabindex="-1">Posso usar o SoftForge sem Docker? <a class="header-anchor" href="#posso-usar-o-softforge-sem-docker" aria-label="Permalink to &quot;Posso usar o SoftForge sem Docker?&quot;">​</a></h3><p><strong>Sim.</strong> Durante o desenvolvimento e criação de protótipos, você pode rodar a API usando o ambiente virtual Python (<code>.venv</code>) e o frontend com <code>npm run dev</code>. Os testes automatizados utilizam SQLite in-memory, o que dispensa qualquer banco externo.</p><h3 id="como-funciona-a-autenticacao-de-dois-niveis-cookie-bearer" tabindex="-1">Como funciona a autenticação de dois níveis (Cookie + Bearer)? <a class="header-anchor" href="#como-funciona-a-autenticacao-de-dois-niveis-cookie-bearer" aria-label="Permalink to &quot;Como funciona a autenticação de dois níveis (Cookie + Bearer)?&quot;">​</a></h3><p>O SoftForge aceita tokens JWT tanto via cabeçalho <code>Authorization: Bearer &lt;token&gt;</code> quanto via cookie <code>HttpOnly</code> com nome <code>access_token</code>. Isso garante máxima segurança no navegador contra ataques XSS e total compatibilidade com clientes de API externos, apps mobile e ferramentas como Postman.</p><h3 id="o-que-acontece-se-duas-fatias-precisarem-compartilhar-dados" tabindex="-1">O que acontece se duas fatias precisarem compartilhar dados? <a class="header-anchor" href="#o-que-acontece-se-duas-fatias-precisarem-compartilhar-dados" aria-label="Permalink to &quot;O que acontece se duas fatias precisarem compartilhar dados?&quot;">​</a></h3><p>Fatias verticais não devem importar modelos privados umas das outras. Elas compartilham chaves primitivas (como <code>workspace_id: uuid.UUID</code> ou <code>user_id: uuid.UUID</code>). Se houver regras de negócio muito complexas compartilhadas, coloque a lógica em um serviço comum em <code>src/core/</code>.</p><hr><h2 id="_2-solucao-de-problemas-comuns" tabindex="-1">2. Solução de Problemas Comuns <a class="header-anchor" href="#_2-solucao-de-problemas-comuns" aria-label="Permalink to &quot;2. Solução de Problemas Comuns&quot;">​</a></h2><h3 id="erro-modulenotfounderror-no-module-named-greenlet" tabindex="-1">Erro: <code>ModuleNotFoundError: No module named &#39;greenlet&#39;</code> <a class="header-anchor" href="#erro-modulenotfounderror-no-module-named-greenlet" aria-label="Permalink to &quot;Erro: `ModuleNotFoundError: No module named &#39;greenlet&#39;`&quot;">​</a></h3><ul><li><strong>Causa:</strong> O SQLAlchemy 2.0 assíncrono requer a biblioteca <code>greenlet</code>.</li><li><strong>Solução:</strong> Execute <code>pip install &quot;greenlet&gt;=3.0.0&quot;</code> no seu ambiente virtual.</li></ul><h3 id="erro-port-8000-or-5173-already-in-use" tabindex="-1">Erro: <code>Port 8000 or 5173 already in use</code> <a class="header-anchor" href="#erro-port-8000-or-5173-already-in-use" aria-label="Permalink to &quot;Erro: `Port 8000 or 5173 already in use`&quot;">​</a></h3><ul><li><strong>Causa:</strong> Outro processo está ocupando as portas padrão da API ou do Vite.</li><li><strong>Solução:</strong> Altere a porta em <code>.env</code> (<code>API_PORT=8001</code>) ou finalize o processo anterior.</li></ul><h3 id="como-resetar-o-banco-de-dados-local-no-docker" tabindex="-1">Como resetar o banco de dados local no Docker? <a class="header-anchor" href="#como-resetar-o-banco-de-dados-local-no-docker" aria-label="Permalink to &quot;Como resetar o banco de dados local no Docker?&quot;">​</a></h3><p>Execute:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> down</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span></span></code></pre></div><p>Isso destruirá o volume <code>pgdata</code> e criará uma base limpa.</p>',20)])])}const h=e(t,[["render",i]]);export{p as __pageData,h as default};
